fields.InputDefinition:
{
  "goal": "Open the application switcher dropdown next to the logo and choose 'Credentials', then click 'Credentials' in the left nav. Then walk these controls IN ORDER, and as you arrive at each one set \"checkpointReached\" to the exact checkpoint name shown: (1) credential-create-panel — click the 'New Credential' button in the top-right and confirm a slide-in edit panel opens rendering a credential-type selector and, once a type is chosen, a dynamic set of schema-driven fields (including any secret/password fields shown as masked inputs); then close/cancel — you do NOT need to save a real credential; (2) credentials-status-filter — open the Filters popover in the toolbar and set Status to 'Active' (then try 'Expiring Soon' or 'Expired') and confirm the credential cards/rows respond (the visible set narrows to matches OR a clear 'No credentials match your current filters' empty state appears), and confirm each credential shows a derived colored status pill (Active / Inactive / Expiring Soon / Expired); (3) credentials-bulk-bar — clear any filters so credentials are visible, then select two or more credentials using the card/row checkboxes and confirm a bulk actions bar appears showing the selected count, a 'Clear selection' link, and bulk buttons (Activate / Deactivate / Delete); click 'Clear selection' and confirm the bar dismisses (if fewer than two credentials exist, confirming the selection checkboxes are present is acceptable; if NO credentials exist at all, confirming the documented 'No Credentials Found' empty state is acceptable) — do NOT actually delete anything. Keep going until every control has been exercised. Pages can take 10-30s to load in this resource-constrained environment — wait for content rather than navigating away.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "finalUrlPattern": "^http://localhost:4200",
  "minConfidence": 0.7,
  "maxSteps": 45,
  "checkpoints": [
    {
      "name": "credential-create-panel",
      "instruction": "open the New Credential slide-in panel",
      "visualCriteria": [
        "Clicking 'New Credential' opens a slide-in edit panel showing a credential-type selector and dynamic schema-driven fields once a type is chosen, with any secret/password fields rendered as masked inputs"
      ]
    },
    {
      "name": "credentials-status-filter",
      "instruction": "filter credentials by derived status",
      "visualCriteria": [
        "Opening the Filters popover and selecting a Status narrows the visible credentials (or shows a no-match empty state), and credential cards/rows display a derived status pill (Active / Inactive / Expiring Soon / Expired)"
      ]
    },
    {
      "name": "credentials-bulk-bar",
      "instruction": "select credentials and use the bulk actions bar",
      "visualCriteria": [
        "Selecting one or more credentials reveals a bulk actions bar with a live selected-count, Activate / Deactivate / Delete buttons, and a 'Clear selection' link that dismisses the bar — OR, if fewer than two credentials exist, selection checkboxes are present"
      ]
    }
  ]
}
